export interface ConnectorConfig {
  /** Brevo API key from environment variable BREVO_API_KEY */
  brevoApiKey: string
  /** Numeric list IDs to subscribe the contact to (configured in Brevo) */
  listIds: number[]
  /** Injected fetch for testing; defaults to global fetch */
  fetch?: typeof fetch
}

export interface TypeformPayload {
  event_id: string
  event_type: string
  form_response: {
    form_id: string
    token: string
    submitted_at: string
    answers: Array<{
      type: string
      email?: string
      text?: string
      field: {
        id: string
        type: string
      }
    }>
  }
}

export interface HandleResult {
  contactId: number
}

function extractEmail(answers: TypeformPayload['form_response']['answers']): string {
  const emailAnswer = answers.find((a) => a.type === 'email' && a.email)
  if (!emailAnswer?.email) {
    throw new Error('Required email field not found in Typeform answers')
  }
  return emailAnswer.email
}

function extractName(answers: TypeformPayload['form_response']['answers']): string | undefined {
  const nameAnswer = answers.find((a) => a.type === 'text' && a.text)
  return nameAnswer?.text
}

function splitName(fullName: string | undefined): { firstName: string; lastName: string } {
  if (!fullName) return { firstName: '', lastName: '' }
  const parts = fullName.trim().split(/\s+/)
  return {
    firstName: parts[0] ?? '',
    lastName: parts.slice(1).join(' ') ?? ''
  }
}

export async function handle(payload: TypeformPayload, config: ConnectorConfig): Promise<HandleResult> {
  if (!payload || payload.event_type !== 'form_response') {
    throw new Error('Invalid payload: expected event_type "form_response"')
  }
  if (!payload.form_response?.answers?.length) {
    throw new Error('Invalid payload: missing form_response.answers')
  }

  const email = extractEmail(payload.form_response.answers)
  const fullName = extractName(payload.form_response.answers)
  const { firstName, lastName } = splitName(fullName)

  if (!config.brevoApiKey) {
    throw new Error('Missing required config: brevoApiKey')
  }
  if (!config.listIds?.length) {
    throw new Error('Missing required config: listIds (at least one list ID required)')
  }

  const body = {
    email,
    attributes: {
      FNAME: firstName,
      LNAME: lastName
    },
    listIds: config.listIds
  }

  const fetchFn = config.fetch ?? fetch
  const response = await fetchFn('https://api.brevo.com/v3/contacts', {
    method: 'POST',
    headers: {
      'api-key': config.brevoApiKey,
      'Content-Type': 'application/json',
      Accept: 'application/json'
    },
    body: JSON.stringify(body)
  })

  if (!response.ok) {
    const text = await response.text().catch(() => '')
    throw new Error(`Brevo API error: ${response.status} ${response.statusText} at POST /v3/contacts - ${text}`)
  }

  const data = (await response.json()) as { id: number }
  if (typeof data.id !== 'number') {
    throw new Error('Brevo API response missing contact id')
  }

  return { contactId: data.id }
}

import { describe, it, expect, vi } from 'vitest'
import { handle, ConnectorConfig, TypeformPayload } from './connector'
