} from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      brevoApiKey: 'test-api-key',
      listIds: [123],
      fetch
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as TypeformPayload, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.contactId).toBe(123)
  })
})

describe('handle', () => {
  it('creates contact and subscribes to list on happy path', async () => {
    const { fetch, calls } = fakeFetch((req) =>
      req.url === 'https://api.brevo.com/v3/contacts' && req.method === 'POST'
        ? jsonResponse({ id: 456 }, 201)
        : jsonResponse({ error: 'not found' }, 404)
    )

    const payload: TypeformPayload = {
      event_id: 'evt-1',
      event_type: 'form_response',
      form_response: {
        form_id: 'form-1',
        token: 'tok-1',
        submitted_at: '2024-01-01T00:00:00Z',
        answers: [
          { type: 'email', email: 'john@example.com', field: { id: 'f1', type: 'email' } },
          { type: 'text', text: 'John Doe', field: { id: 'f2', type: 'short_text' } }
        ]
      }
    }

    const config: ConnectorConfig = {
      brevoApiKey: 'api-key-123',
      listIds: [10, 20],
      fetch
    }

    const result = await handle(payload, config)

    expect(result.contactId).toBe(456)
    expect(calls).toHaveLength(1)
    const call = calls[0]
    expect(call.method).toBe('POST')
    expect(call.url).toBe('https://api.brevo.com/v3/contacts')
    expect(call.headers.get('api-key')).toBe('api-key-123')
    expect(call.json).toEqual({
      email: 'john@example.com',
      attributes: { FNAME: 'John', LNAME: 'Doe' },
      listIds: [10, 20]
    })
  })

  it('uses only first name when last name not provided', async () => {
    const { fetch, calls } = fakeFetch((req) =>
      req.url === 'https://api.brevo.com/v3/contacts' ? jsonResponse({ id: 789 }, 201) : jsonResponse({}, 404)
    )

    const payload: TypeformPayload = {
      event_id: 'evt-2',
      event_type: 'form_response',
      form_response: {
        form_id: 'form-1',
        token: 'tok-2',
