        answers: [
          { type: 'email', email: 'jane@example.com', field: { id: 'f1', type: 'email' } },
          { type: 'text', text: 'Jane', field: { id: 'f2', type: 'short_text' } }
        ]
      }
    }

    const config: ConnectorConfig = { brevoApiKey: 'key', listIds: [5], fetch }
    const result = await handle(payload, config)

    expect(result.contactId).toBe(789)
    expect(calls[0].json).toEqual({
      email: 'jane@example.com',
      attributes: { FNAME: 'Jane', LNAME: '' },
      listIds: [5]
    })
  })

  it('throws when email is missing from answers', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))

    const payload: TypeformPayload = {
      event_id: 'evt-3',
      event_type: 'form_response',
      form_response: {
        form_id: 'form-1',
        token: 'tok-3',
        submitted_at: '2024-01-01T00:00:00Z',
        answers: [{ type: 'text', text: 'No Email', field: { id: 'f1', type: 'short_text' } }]
