      event_id: 'evt-5',
      event_type: 'form_response',
      form_response: {
        form_id: 'form-1',
        token: 'tok-5',
        submitted_at: '2024-01-01T00:00:00Z',
        answers: [{ type: 'email', email: 'test@example.com', field: { id: 'f1', type: 'email' } }]
      }
    }

    const config: ConnectorConfig = { brevoApiKey: '', listIds: [1], fetch }
    await expect(handle(payload, config)).rejects.toThrow('Missing required config: brevoApiKey')
